    #[test]
    fn a_failed_verdict_fails_the_task() {
        let run = |mode: SendMode, reply: &str| {
            let mut task = PromptTask::new("Do it".into());
            task.mode = Some(mode);
            task.set_compiled(super::Compiled::new("Prompt_0".into(), "Do it".into()));
